import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第十一卦 泰 天地泰 坤上乾下","description":"周易 - 第十一卦 泰 天地泰 坤上乾下","frontmatter":{"title":"第十一卦 泰 天地泰 坤上乾下","description":"周易 - 第十一卦 泰 天地泰 坤上乾下"},"headers":[],"relativePath":"zh/classics/zhouyi/012.md","filePath":"zh/classics/zhouyi/012.md"}'),l={name:"zh/classics/zhouyi/012.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="泰" tabindex="-1">泰 <a class="header-anchor" href="#泰" aria-label="Permalink to “泰”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>小往大来，吉亨。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>泰，小往大来，吉亨。则是天地交，而万物通也；上下交，而其志同也。内阳而外阴，内健而外顺，内君子而外小人，君子道长，小人道消也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>天地交泰，后以财（裁）成天地之道，辅相天地之宜，以左右民。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>拔茅 茹，以其夤，征吉。象曰：拔茅征吉，志在外也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>包荒，用冯河，不遐遗，朋亡，得尚于中行。象曰：包荒，得尚于中行，以光大也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>无平不陂，无往不复，艰贞无咎。勿恤其孚，于食有福。象曰：无往不复，天地际也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>翩翩不富，以其邻，不戒以孚。象曰：翩翩不富，皆失实也。不戒以孚，中心愿也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>帝乙归妹，以祉元吉。象曰：以祉元吉，中以行愿也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>城复于隍，勿用师。自邑告命，贞吝。象曰：城复于隍，其命乱也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
